"use client";

import Image from "next/image";
import Link from "next/link";
import { Menu, Moon, Sun, X } from "lucide-react";
import { useEffect, useState } from "react";
import { switchTheme, useTheme } from "@/components/theme";

const links = [
  { href: "#how", label: "How it works", id: "how" },
  { href: "#features", label: "Features", id: "features" },
  { href: "#pricing", label: "Pricing", id: "pricing" },
] as const;

export function Navbar({
  signInAction,
}: {
  signInAction: () => Promise<void>;
}) {
  const [compact, setCompact] = useState(false);
  const [open, setOpen] = useState(false);
  const [active, setActive] = useState<string | null>(null);
  const theme = useTheme();

  useEffect(() => {
    const update = () => setCompact(window.scrollY > 12);
    update();
    window.addEventListener("scroll", update, { passive: true });
    return () => window.removeEventListener("scroll", update);
  }, []);

  useEffect(() => {
    if (!window.IntersectionObserver) return;
    const observer = new IntersectionObserver(
      (entries) => {
        const visible = entries.filter((entry) => entry.isIntersecting);
        if (visible.length) {
          visible.sort((a, b) => b.intersectionRatio - a.intersectionRatio);
          setActive(visible[0].target.id);
        } else if (window.scrollY < 100) {
          setActive(null);
        }
      },
      { rootMargin: "-20% 0px -60% 0px", threshold: [0, 0.25, 0.5, 1] },
    );
    links.forEach(({ id }) => {
      const section = document.getElementById(id);
      if (section) observer.observe(section);
    });
    return () => observer.disconnect();
  }, []);

  useEffect(() => {
    if (!open) return;
    const onEscape = (event: KeyboardEvent) => {
      if (event.key === "Escape") setOpen(false);
    };
    window.addEventListener("keydown", onEscape);
    return () => window.removeEventListener("keydown", onEscape);
  }, [open]);

  const linkClass = (id: string) =>
    `inline-flex min-h-11 items-center rounded-full px-3 text-sm font-medium transition-colors css-hover:text-[var(--landing-accent-text)] focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[var(--landing-accent-text)] ${active === id ? "text-[var(--landing-accent-text)]" : "text-[var(--landing-muted)]"}`;

  return (
    <header
      className="landing-navbar fixed inset-x-0 top-0 z-50 mx-auto w-full px-4 pt-4 sm:px-8 sm:pt-5"
      data-compact={compact}
    >
      <div className="relative mx-auto max-w-300">
        <div className="landing-navbar-pill flex min-h-16 items-center justify-between gap-2 rounded-full border border-[var(--landing-line2)] bg-[color-mix(in_srgb,var(--landing-card)_82%,transparent)] px-3 shadow-lg shadow-[color-mix(in_srgb,var(--landing-bg)_35%,transparent)] backdrop-blur-xl sm:px-5 lg:px-7">
          <Link
            href="/"
            className="landing-logo inline-flex min-h-11 shrink-0 items-center gap-2.5 rounded-full text-xl font-bold tracking-[-0.04em] focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[var(--landing-accent-text)] sm:text-2xl"
            aria-label="Mailloop home"
            translate="no"
          >
            <span className="grid size-9 shrink-0 place-items-center rounded-[10px] bg-[var(--landing-accent)] shadow-[0_0_28px_var(--color-landing-box-shadow-68)]">
              <Image
                src="/icon.svg"
                alt=""
                width={36}
                height={36}
                className="size-full"
                unoptimized
              />
            </span>
            <span>mailloop</span>
          </Link>
          <nav
            aria-label="Main navigation"
            className="hidden items-center gap-1 md:flex"
          >
            {links.map(({ href, label, id }) => (
              <a
                key={id}
                href={href}
                aria-current={active === id ? "location" : undefined}
                className={linkClass(id)}
              >
                {label}
              </a>
            ))}
          </nav>
          <div className="flex shrink-0 items-center gap-1 sm:gap-2">
            <button
              type="button"
              aria-label={`Switch to ${theme === "dark" ? "light" : "dark"} theme`}
              onClick={(event) =>
                switchTheme(
                  theme === "dark" ? "light" : "dark",
                  event.currentTarget,
                )
              }
              className="grid size-11 place-items-center rounded-full text-[var(--landing-muted)] css-hover:text-[var(--landing-accent-text)] focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[var(--landing-accent-text)]"
            >
              {theme === "dark" ? (
                <Sun size={20} aria-hidden="true" />
              ) : (
                <Moon size={20} aria-hidden="true" />
              )}
            </button>
            <form action={signInAction} className="hidden sm:block">
              <button
                type="submit"
                className="landing-navbar-signin inline-flex min-h-11 items-center justify-center rounded-full border border-[var(--landing-line2)] px-5 text-sm font-semibold text-[var(--landing-fg)] css-hover:border-[var(--landing-accent-text)] focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[var(--landing-accent-text)]"
              >
                Sign in
              </button>
            </form>
            <button
              type="button"
              aria-label={open ? "Close menu" : "Open menu"}
              aria-expanded={open}
              aria-controls="landing-mobile-menu"
              onClick={() => setOpen((value) => !value)}
              className="grid size-11 place-items-center rounded-full text-[var(--landing-fg)] focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[var(--landing-accent-text)] md:hidden"
            >
              {open ? (
                <X size={22} aria-hidden="true" />
              ) : (
                <Menu size={22} aria-hidden="true" />
              )}
            </button>
          </div>
        </div>
        <nav
          id="landing-mobile-menu"
          aria-label="Mobile navigation"
          inert={!open}
          hidden={!open}
          className="landing-navbar-menu absolute inset-x-0 top-full mt-2 rounded-3xl border border-[var(--landing-line2)] bg-[var(--landing-card)] p-3 shadow-xl md:hidden"
        >
          {links.map(({ href, label, id }) => (
            <a
              key={id}
              href={href}
              aria-current={active === id ? "location" : undefined}
              onClick={() => setOpen(false)}
              className={`${linkClass(id)} flex w-full px-4`}
            >
              {label}
            </a>
          ))}
          <form action={signInAction}>
            <button
              type="submit"
              className="inline-flex min-h-11 w-full items-center rounded-full px-4 text-sm font-semibold text-[var(--landing-accent-text)] focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[var(--landing-accent-text)]"
            >
              Sign in
            </button>
          </form>
        </nav>
      </div>
    </header>
  );
}
